static const uint32_t DEFAULT_BLOCK_DIM = 8;
static const uint32_t DEFAULT_TILEN = 256;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // Shapes:
    // x: [M, K]
    // weight: [N, K]
    const auto* xShape = context->GetInputShape(0);
    const auto* wShape = context->GetInputShape(1);
    if (xShape == nullptr || wShape == nullptr) {
        return ge::GRAPH_FAILED;
    }

    const auto xOrigin = xShape->GetOriginShape();
    const auto wOrigin = wShape->GetOriginShape();
    if (xOrigin.GetDimNum() != 2 || wOrigin.GetDimNum() != 2) {
        return ge::GRAPH_FAILED;
    }

    uint32_t M = static_cast<uint32_t>(xOrigin.GetDim(0));
    uint32_t K = static_cast<uint32_t>(xOrigin.GetDim(1));
    uint32_t N = static_cast<uint32_t>(wOrigin.GetDim(0));

    GemmScaleBatchNormCustomTilingData tiling;
    tiling.set_M(M);
    tiling.set_N(N);
    tiling.set_K(K);
    uint32_t tileN = DEFAULT_TILEN;
    if (tileN == 0 || tileN > N) {
        tileN = N;
    }
    tiling.set_tileN(tileN);

    // block dim
    context->SetBlockDim(DEFAULT_BLOCK_DIM);

    // Save tiling to buffer
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // workspace (none)
    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);   // [M, K]
    const gert::Shape* w_shape = context->GetInputShape(1);   // [N, K]
    if (x_shape == nullptr || w_shape == nullptr) {
        return GRAPH_FAILED;
    }
    gert::Shape* y_shape = context->GetOutputShape(0);
    gert::Shape out;
    if (x_shape->GetDimNum() != 2 || w_shape->GetDimNum() != 2) {
        return GRAPH_FAILED;
    }
    int64_t M = x_shape->GetDim(0);
    int64_t N = w_shape->GetDim(0);
    out.SetDimNum(2);
    out.SetDim(0, M);
    out.SetDim(1, N);
    *y_shape = out;
    return GRAPH_SUCCESS;
}

